style.css:
/* ===== MEGA RAYQUAZA BACKGROUND (CORRECT) ===== */

body {
  background: radial-gradient(circle at top,
    #16ff9d 0%,
    #012117 45%,
    #000000 100%
  ) !important;
  overflow-x: hidden;
}

/* Cosmic emerald aura */
body::before {
  content: "";
  position: fixed;
  inset: -60%;
  background: conic-gradient(
    #00ff99,
    #ffe066,
    #00cc66,
    #ffe066,
    #00ff99
  );
  animation: megaSpin 45s linear infinite;
  opacity: 0.22;
  filter: blur(140px);
  z-index: -2;
}

@keyframes megaSpin {
  to { transform: rotate(360deg); }
}

/* ? MEGA RAYQUAZA IMAGE ? */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  background-image: url("https://archives.bulbagarden.net/media/upload/3/3a/384Rayquaza-Mega.png");
  background-repeat: no-repeat;
  background-position: center;
  background-size: min(72vh, 72vw);
  opacity: 0.9;
  filter:
    drop-shadow(0 0 45px rgba(0,255,153,0.9))
    drop-shadow(0 0 90px rgba(255,224,102,0.7));
  animation: megaFloat 6s ease-in-out infinite;
  pointer-events: none;
  z-index: -1;
}

@keyframes megaFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-22px); }
}

/* Improve readability */
* {
  text-shadow: 0 0 10px rgba(0,255,153,0.35);
}

div, section, article {
  background-color: rgba(0, 0, 0, 0.35) !important;
  backdrop-filter: blur(6px);
}
